using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Fleet.Api.Data;using Fleet.Api.Models;using Fleet.Api.Services;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;
var builder=WebApplication.CreateBuilder(args);var secret=builder.Configuration["Jwt:Secret"]??"development-only-secret-change-me-32-characters";builder.Services.AddDbContext<FleetDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("Default")??"Data Source=fleet.db"));builder.Services.AddScoped<IPasswordHasher<User>,PasswordHasher<User>>();builder.Services.AddScoped<AssignmentService>();builder.Services.AddOpenApi();builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret))});builder.Services.AddAuthorization();
var app=builder.Build();app.UseExceptionHandler("/error");app.UseAuthentication();app.UseAuthorization();if(app.Environment.IsDevelopment())app.MapOpenApi();app.Map("/error",()=>Results.Json(new{error=new{code="SERVER_ERROR",message="Request could not be completed"}},statusCode:500));
app.MapPost("/api/auth/login",async(Login input,FleetDbContext db,IPasswordHasher<User> h)=>{var u=await db.Users.SingleOrDefaultAsync(x=>x.Username==input.Username);if(u==null||h.VerifyHashedPassword(u,u.PasswordHash,input.Password)==PasswordVerificationResult.Failed)return Results.Unauthorized();var claims=new List<Claim>{new(ClaimTypes.NameIdentifier,u.Id.ToString()),new(ClaimTypes.Name,u.Username),new(ClaimTypes.Role,u.Role)};if(u.DriverId is int id)claims.Add(new("driver_id",id.ToString()));var token=new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(claims:claims,expires:DateTime.UtcNow.AddHours(2),signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),SecurityAlgorithms.HmacSha256)));return Results.Ok(new{data=new{token,user=new{u.Id,u.Username,u.Role,u.DriverId}}});});
var staff=new[]{"Admin","Dispatcher"};app.MapGet("/api/vehicles",async(string? search,int page,int limit,FleetDbContext db)=>{page=Math.Max(1,page);limit=Math.Clamp(limit==0?20:limit,1,100);var q=db.Vehicles.AsNoTracking();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.PlateNumber.Contains(search)||x.MakeModel.Contains(search));return Results.Ok(new{data=await q.OrderBy(x=>x.PlateNumber).Skip((page-1)*limit).Take(limit).ToListAsync(),pagination=new{page,limit,total=await q.CountAsync()}});}).RequireAuthorization();
app.MapPost("/api/vehicles",async(VehicleInput x,FleetDbContext db)=>{if(x.Year<1990||x.Odometer<0||string.IsNullOrWhiteSpace(x.PlateNumber))return Results.BadRequest();if(await db.Vehicles.AnyAsync(v=>v.PlateNumber==x.PlateNumber))return Results.Conflict();var v=new Vehicle{PlateNumber=x.PlateNumber.Trim().ToUpperInvariant(),MakeModel=x.MakeModel.Trim(),Year=x.Year,Odometer=x.Odometer};db.Add(v);await db.SaveChangesAsync();return Results.Created($"/api/vehicles/{v.Id}",new{data=v});}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapGet("/api/drivers",async(FleetDbContext db)=>Results.Ok(new{data=await db.Drivers.AsNoTracking().OrderBy(x=>x.FullName).ToListAsync()})).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPost("/api/drivers",async(DriverInput x,FleetDbContext db)=>{if(await db.Drivers.AnyAsync(d=>d.LicenseNumber==x.LicenseNumber))return Results.Conflict();var d=new Driver{FullName=x.FullName.Trim(),LicenseNumber=x.LicenseNumber.Trim(),LicenseExpiresOn=x.LicenseExpiresOn};db.Add(d);await db.SaveChangesAsync();return Results.Created($"/api/drivers/{d.Id}",new{data=d});}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapGet("/api/assignments",async(ClaimsPrincipal user,FleetDbContext db)=>{var q=db.Assignments.AsNoTracking().Include(x=>x.Vehicle).Include(x=>x.Driver).AsQueryable();if(user.IsInRole("Driver"))q=q.Where(x=>x.DriverId==int.Parse(user.FindFirstValue("driver_id")??"0"));return Results.Ok(new{data=await q.OrderByDescending(x=>x.CreatedAt).ToListAsync()});}).RequireAuthorization();
app.MapPost("/api/assignments",async(AssignmentInput x,ClaimsPrincipal u,AssignmentService s)=>{try{return Results.Created("/api/assignments",new{data=await s.AssignAsync(x.VehicleId,x.DriverId,x.StartsAt,x.Purpose,int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!))});}catch(ArgumentException e){return Results.BadRequest(new{error=new{code="VALIDATION_ERROR",message=e.Message}});}catch(KeyNotFoundException){return Results.NotFound();}catch(InvalidOperationException e){return Results.Conflict(new{error=new{code="CONFLICT",message=e.Message}});}}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPatch("/api/assignments/{id:int}/complete",async(int id,CompleteInput x,AssignmentService s)=>{try{return Results.Ok(new{data=await s.CompleteAsync(id,x.Odometer)});}catch(KeyNotFoundException){return Results.NotFound();}catch(ArgumentException e){return Results.BadRequest(new{error=new{code="VALIDATION_ERROR",message=e.Message}});}catch(InvalidOperationException e){return Results.Conflict(new{error=new{code="CONFLICT",message=e.Message}});}}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapGet("/api/maintenance",async(FleetDbContext db)=>Results.Ok(new{data=await db.MaintenanceRecords.AsNoTracking().Include(x=>x.Vehicle).OrderByDescending(x=>x.ServicedOn).ToListAsync()})).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPost("/api/maintenance",async(MaintenanceInput x,FleetDbContext db)=>{var v=await db.Vehicles.FindAsync(x.VehicleId);if(v==null)return Results.NotFound();if(x.Odometer<v.Odometer||x.Cost<0||string.IsNullOrWhiteSpace(x.ServiceType))return Results.BadRequest();v.Odometer=x.Odometer;var m=new MaintenanceRecord{VehicleId=x.VehicleId,ServiceType=x.ServiceType.Trim(),Odometer=x.Odometer,Cost=x.Cost,ServicedOn=x.ServicedOn,Notes=x.Notes??""};db.Add(m);await db.SaveChangesAsync();return Results.Created($"/api/maintenance/{m.Id}",new{data=m});}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapGet("/api/dashboard",async(FleetDbContext db)=>Results.Ok(new{data=new{vehicles=await db.Vehicles.CountAsync(),available=await db.Vehicles.CountAsync(x=>x.Status=="Available"),activeAssignments=await db.Assignments.CountAsync(x=>x.EndsAt==null),expiringLicenses=await db.Drivers.CountAsync(x=>x.LicenseExpiresOn<=DateOnly.FromDateTime(DateTime.UtcNow.AddDays(30)))}})).RequireAuthorization(p=>p.RequireRole(staff));
await using(var scope=app.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<FleetDbContext>();await db.Database.EnsureCreatedAsync();if(!await db.Users.AnyAsync()){var h=scope.ServiceProvider.GetRequiredService<IPasswordHasher<User>>();var driver=new Driver{FullName="Demo Driver",LicenseNumber="LIC-001",LicenseExpiresOn=DateOnly.FromDateTime(DateTime.UtcNow.AddYears(1))};db.Drivers.Add(driver);foreach(var (n,r,d) in new[]{("admin","Admin",(Driver?)null),("dispatcher","Dispatcher",null),("driver","Driver",driver)}){var u=new User{Username=n,Role=r,PasswordHash="x",DriverId=d?.Id};if(d!=null)u.DriverId=null;u.PasswordHash=h.HashPassword(u,"ChangeMe123!");db.Users.Add(u);}db.Vehicles.Add(new Vehicle{PlateNumber="DEMO-001",MakeModel="Demo Van",Year=2025,Odometer=1000});await db.SaveChangesAsync();var du=await db.Users.SingleAsync(x=>x.Username=="driver");du.DriverId=driver.Id;await db.SaveChangesAsync();}}
app.Run();public partial class Program;public sealed record Login(string Username,string Password);public sealed record VehicleInput(string PlateNumber,string MakeModel,int Year,int Odometer);public sealed record DriverInput(string FullName,string LicenseNumber,DateOnly LicenseExpiresOn);public sealed record AssignmentInput(int VehicleId,int DriverId,DateTime StartsAt,string Purpose);public sealed record CompleteInput(int Odometer);public sealed record MaintenanceInput(int VehicleId,string ServiceType,int Odometer,decimal Cost,DateOnly ServicedOn,string? Notes);
